# === PyGen 注入：HTTP/SSL 韧性层（通用） ===
# 说明：
# 1) 优先保持 verify=True；如确需临时绕过（不推荐），可设置环境变量 PYGEN_INSECURE_SSL=1
# 2) 默认遇到 418/403/429 仅做一次"预热 cookie + 浏览器化 headers"的重试
# 3) 若仍被拦截且本机已安装 Playwright，会自动尝试一次 request-context 兜底
#    如需禁用：设置 PYGEN_DISABLE_PLAYWRIGHT_FALLBACK=1
import os as _pygen_os
import ssl as _pygen_ssl
import urllib.parse as _pygen_urlparse

try:
    # truststore 会让 Python/requests 使用系统证书库（Windows/macOS/Linux），更贴近浏览器行为
    import truststore as _pygen_truststore  # type: ignore
    _pygen_truststore.inject_into_ssl()
except Exception:
    _pygen_truststore = None  # noqa: F401

try:
    import requests as _pygen_requests
    from requests.structures import CaseInsensitiveDict as _pygen_CaseInsensitiveDict
except Exception:
    _pygen_requests = None  # noqa: F401

_PYGEN_DEFAULT_UA = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
    "AppleWebKit/537.36 (KHTML, like Gecko) "
    "Chrome/122.0 Safari/537.36"
)

def _pygen_origin(url: str) -> str:
    try:
        p = _pygen_urlparse.urlsplit(url)
        return f"{p.scheme}://{p.netloc}"
    except Exception:
        return ""

def _pygen_merge_headers(h: dict | None) -> dict:
    base = {
        "User-Agent": _PYGEN_DEFAULT_UA,
        "Accept": "application/json,text/plain,*/*",
        "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
        "Connection": "keep-alive",
    }
    if h:
        for k, v in h.items():
            if v is not None:
                base[k] = v
    return base

def _pygen_make_response(status: int, url: str, headers: dict, body: bytes):
    r = _pygen_requests.Response()
    r.status_code = status
    r.url = url
    r.headers = _pygen_CaseInsensitiveDict(headers or {})
    r._content = body or b""
    return r

def _pygen_playwright_fetch(method: str, url: str, headers: dict, data=None, json=None, timeout: int = 30):
    """
    兜底：使用 Playwright 的 request context（更像浏览器/更容易过 WAF）。
    仅当已安装 playwright 且未设置 PYGEN_DISABLE_PLAYWRIGHT_FALLBACK=1 时启用。
    """
    if _pygen_os.getenv("PYGEN_DISABLE_PLAYWRIGHT_FALLBACK") == "1":
        return None
    try:
        from playwright.sync_api import sync_playwright  # type: ignore
    except Exception:
        return None

    with sync_playwright() as p:
        ctx = p.request.new_context(ignore_https_errors=_pygen_os.getenv("PYGEN_INSECURE_SSL") == "1",
                                    extra_http_headers=headers)
        try:
            resp = ctx.fetch(url, method=method.upper(), data=data, json=json, timeout=timeout * 1000)
            body = resp.body()
            return _pygen_make_response(resp.status, url, dict(resp.headers), body)
        finally:
            ctx.dispose()

def _pygen_install_requests_patch():
    if _pygen_requests is None:
        return
    _orig = _pygen_requests.sessions.Session.request

    def _patched(self, method, url, **kwargs):
        # 默认超时，避免脚本卡死
        kwargs.setdefault("timeout", 30)

        # 证书校验策略：默认开启；仅在用户明确设置时关闭
        if _pygen_os.getenv("PYGEN_INSECURE_SSL") == "1":
            kwargs["verify"] = False

        # 合并"更像浏览器"的 headers（很多站会对 UA/Accept 做拦截）
        headers = _pygen_merge_headers(kwargs.get("headers"))
        kwargs["headers"] = headers

        # 首次请求
        try:
            resp = _orig(self, method, url, **kwargs)
        except Exception as e:
            # 若是 SSL 校验错误：truststore 已注入则直接抛出；否则给出更友好的提示
            msg = str(e)
            if "CERTIFICATE_VERIFY_FAILED" in msg or "certificate verify failed" in msg:
                # 若 playwright 可用，尝试用 request-context 做一次兜底（有些环境下系统信任链更完整）
                try:
                    pw_resp = _pygen_playwright_fetch(method, url, headers=headers,
                                                      data=kwargs.get("data"),
                                                      json=kwargs.get("json"),
                                                      timeout=int(kwargs.get("timeout") or 30))
                    if pw_resp is not None:
                        return pw_resp
                except Exception:
                    pass
                raise
            raise

        # WAF/反爬：做一次轻量重试（预热 cookie + 再请求）
        if resp is not None and getattr(resp, "status_code", 0) in (418, 403, 429):
            try:
                origin = _pygen_origin(url)
                if origin:
                    # 预热：访问首页拿 cookie
                    _ = _orig(self, "GET", origin + "/", headers=headers, timeout=15, verify=kwargs.get("verify", True))
                resp2 = _orig(self, method, url, **kwargs)
                if resp2 is not None and getattr(resp2, "status_code", 0) not in (418, 403, 429):
                    return resp2
                # 若仍被拦截，且 playwright 可用，则再尝试一次（自动兜底）
                pw_resp = _pygen_playwright_fetch(method, url, headers=headers,
                                                  data=kwargs.get("data"),
                                                  json=kwargs.get("json"),
                                                  timeout=int(kwargs.get("timeout") or 30))
                if pw_resp is not None:
                    return pw_resp
            except Exception:
                # 兜底失败则返回原始响应，交由上层处理
                return resp

        return resp

    _pygen_requests.sessions.Session.request = _patched

_pygen_install_requests_patch()
# === PyGen 注入结束 ===
import os
import json
import asyncio
import re
from datetime import datetime, timedelta
from urllib.parse import urljoin
from bs4 import BeautifulSoup
from playwright.async_api import async_playwright

# ================= 配置区域 =================
OUTPUT_DIR = r"d:\llm_mcp_genpy\pygen\output"
TARGET_URL = "https://www.news.bundesbank.de/news-de"
MAX_ITEMS = 5  # 任务目标：前5条

# ================= 工具函数 =================

def clean_html_content(html_content, base_url):
    """
    清洗HTML内容：将相对路径转换为绝对路径
    """
    if not html_content:
        return ""
    try:
        soup = BeautifulSoup(html_content, 'html.parser')

        # 修复图片链接
        for img in soup.find_all('img'):
            if img.get('src'):
                img['src'] = urljoin(base_url, img['src'])

        # 修复超链接
        for a in soup.find_all('a'):
            if a.get('href'):
                a['href'] = urljoin(base_url, a['href'])

        return str(soup)
    except Exception as e:
        print(f"[Warn] 内容清洗出错: {e}")
        return html_content

def parse_german_date(date_str):
    """
    解析德语/社交媒体格式的日期字符串
    """
    if not date_str:
        return datetime.now().strftime("%Y-%m-%d")

    date_str = date_str.strip()
    today = datetime.now()

    try:
        # 处理相对时间 (e.g., "vor 2 Stunden", "2h", "3d")
        if 'vor' in date_str or re.search(r'\d+[hm]', date_str):
            if 'Stunde' in date_str or 'h' in date_str:
                return today.strftime("%Y-%m-%d")
            if 'Tag' in date_str or 'd' in date_str:
                days = int(re.search(r'(\d+)', date_str).group(1))
                return (today - timedelta(days=days)).strftime("%Y-%m-%d")
            if 'Minute' in date_str or 'm' in date_str:
                return today.strftime("%Y-%m-%d")

        # 处理德语月份
        german_months = {
            'Jan': '01', 'Feb': '02', 'Mär': '03', 'Apr': '04', 'Mai': '05', 'Jun': '06',
            'Jul': '07', 'Aug': '08', 'Sep': '09', 'Okt': '10', 'Nov': '11', 'Dez': '12',
            'Januar': '01', 'Februar': '02', 'März': '03', 'April': '04', 'Mai': '05', 'Juni': '06',
            'Juli': '07', 'August': '08', 'September': '09', 'Oktober': '10', 'November': '11', 'Dezember': '12'
        }

        # 尝试匹配 "DD. Month YYYY" 或 "DD. Month"
        # 移除不需要的字符
        clean_date = re.sub(r'[.,]', '', date_str)
        parts = clean_date.split()

        day = parts[0].zfill(2)
        month = "01"
        year = str(today.year)

        if len(parts) >= 2:
            month_str = parts[1]
            month = german_months.get(month_str, "01")

        if len(parts) >= 3:
            year = parts[2]

        return f"{year}-{month}-{day}"

    except Exception:
        # 解析失败返回当天
        return today.strftime("%Y-%m-%d")

def save_results(articles: list, output_path: str):
    """
    保存结果为JSON
    """
    result = {
        "total": len(articles),
        "crawlTime": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "articles": articles
    }
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
    print(f"[Success] 已保存 {len(articles)} 条新闻到 {output_path}")

# ================= 核心爬虫逻辑 =================

async def crawl_news():
    print(f"[Info] 启动爬虫，目标: {TARGET_URL}")

    async with async_playwright() as p:
        # 启动浏览器（配置反爬参数）
        browser = await p.chromium.launch(
            headless=True,
            args=["--disable-blink-features=AutomationControlled", "--no-sandbox"]
        )

        context = await browser.new_context(
            viewport={'width': 1920, 'height': 1080},
            user_agent="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            locale="de-DE"
        )

        page = await context.new_page()

        try:
            # 1. 访问页面
            await page.goto(TARGET_URL, wait_until="domcontentloaded")

            # 2. 等待 Shadow DOM 宿主元素加载
            print("[Info] 等待 Widget 加载...")
            await page.wait_for_selector("#stage-widget", timeout=15000)

            # 3. 等待 Shadow DOM 内部内容渲染
            # 由于内容在 Shadow DOM 中，我们使用 evaluate 轮询检查内部元素是否存在
            print("[Info] 等待 Shadow DOM 内容渲染...")
            for _ in range(10):
                has_content = await page.evaluate("""() => {
                    const host = document.querySelector('#stage-widget');
                    return host && host.shadowRoot && host.shadowRoot.querySelectorAll('div[tabindex="0"]').length > 0;
                }""")
                if has_content:
                    break
                await asyncio.sleep(1)

            # 额外等待一点时间确保图片和布局稳定
            await asyncio.sleep(2)

            # 4. 提取数据 (核心逻辑：穿透 Shadow DOM)
            # 我们在浏览器上下文中执行 JS，直接从 Shadow Root 提取数据
            print("[Info] 开始提取数据...")
            raw_articles = await page.evaluate("""() => {
                const host = document.querySelector('#stage-widget');
                if (!host || !host.shadowRoot) return [];

                // 根据分析，卡片通常是 div[tabindex="0"]
                const cards = Array.from(host.shadowRoot.querySelectorAll('div[tabindex="0"]'));

                return cards.slice(0, 5).map(card => {
                    // 提取标题/正文文本
                    // 尝试多个可能的文本容器
                    const textEl = card.querySelector('div[class*="text"], p, h3, span[class*="content"]');
                    const title = textEl ? textEl.innerText.trim() : "";

                    // 提取日期
                    // 提示提到 .css-8h7cib，但也尝试通用的 time 标签
                    const dateEl = card.querySelector('time, .css-8h7cib, span[class*="date"], span[class*="time"]');
                    const dateStr = dateEl ? dateEl.innerText.trim() : "";

                    // 提取链接
                    // 通常整个卡片可点击，或者有特定链接
                    const linkEl = card.querySelector('a[href]');
                    const link = linkEl ? linkEl.href : "";

                    // 提取来源/作者
                    const authorEl = card.querySelector('span[class*="name"], div[class*="profile"]');
                    const author = authorEl ? authorEl.innerText.trim() : "Bundesbank";

                    // 提取图片作为内容的一部分
                    const imgEl = card.querySelector('img');
                    const imgSrc = imgEl ? imgEl.src : "";

                    // 构建简单的 HTML 内容
                    let contentHtml = `<p>${title}</p>`;
                    if (imgSrc) {
                        contentHtml += `<img src="${imgSrc}">`;
                    }

                    return {
                        title: title.substring(0, 100) + (title.length > 100 ? "..." : ""), // 截取前部分作为标题
                        full_text: title,
                        date_raw: dateStr,
                        sourceUrl: link,
                        author: author,
                        content: contentHtml
                    };
                });
            }""")

            articles = []
            for idx, item in enumerate(raw_articles, 1):
                # 数据清洗和标准化
                article = {
                    "id": str(idx),
                    "title": item.get("title") or "无标题新闻",
                    "date": parse_german_date(item.get("date_raw")),
                    "source": "Bundesbank Social Media",
                    "author": item.get("author"),
                    "sourceUrl": item.get("sourceUrl") or TARGET_URL,
                    "summary": item.get("full_text")[:200] + "..." if item.get("full_text") else "",
                    "content": clean_html_content(item.get("content"), TARGET_URL)
                }
                articles.append(article)
                print(f"[Data] 抓取到: {article['date']} - {article['title']}")

            return articles

        except Exception as e:
            print(f"[Error] 爬取过程中发生错误: {e}")
            import traceback
            traceback.print_exc()
            return []
        finally:
            await browser.close()

# ================= 主程序入口 =================

def main():
    # 确保输出目录存在
    os.makedirs(OUTPUT_DIR, exist_ok=True)

    # 运行爬虫
    articles = asyncio.run(crawl_news())

    # 保存结果
    if articles:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"bundesbank_news_{timestamp}.json"
        output_path = os.path.join(OUTPUT_DIR, filename)
        save_results(articles, output_path)
    else:
        print("[Warn] 未抓取到任何数据")

if __name__ == "__main__":
    main()
